mapper.select:
select max(created_at) as last_load
from ${table}
where deal_year = #{dealYear} and deal_month = #{dealMonth}

select t.sgg_cd, coalesce(g.sgg_nm, t.sgg_cd) as sgg_nm, t.umd_nm, t.apt_nm, t.apt_dong, t.jibun, t.exclu_use_ar, t.floor, t.build_year, t.deal_year, t.deal_month, t.deal_day, t.deal_amount, t.dealing_gbn, t.cdeal_type, round(t.deal_amount / nullif(t.exclu_use_ar, 0), 1) as amount_per_m2 from estate.apt_trade t left join public.g_sgg g on g.sgg_cd = t.sgg_cd where 1 = 1
and t.sgg_cd = #{sggCd}
and t.apt_nm ilike '%' || #{aptNm} || '%'
order by t.deal_year desc, t.deal_month desc, t.deal_day desc, t.deal_amount desc limit #{limit}
